#!/usr/bin/env python3
"""Predeclared standard20 science gate and paired fingerprints; no builds or timing claim."""
import argparse
import array
import copy
import hashlib
import json
import math
import os
import struct
import subprocess
import sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
sys.path.insert(0,str(ROOT/'scripts'))
import replay_plugins as replay

RULES={
 'scope':'Exact OLS. Eligible auto Fast unsaved two-intercept-FE PPML numerical/work leaves only; protected decisions exact.',
 'coefficient':{'rtol':1e-7,'atol':1e-10},
 'covariance':{'rtol':1e-6,'atol':1e-10},
 'column':{'rtol':1e-7,'atol':1e-9},
 'fit':{'rtol':1e-7,'atol':1e-9},
 'no_hit':'Absent attempted historical reuse requires exact science and all binary columns.',
 'limit':'One baseline and one candidate per standard case; no retries or scope expansion.',
 'timing_binding':'Fingerprint equals bench/time_exact.py exact_view plus full columns_sha256; timing must reproduce the matching preflight arm fingerprint.'}


def digest(path):
    h=hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda:f.read(1<<20),b''):h.update(chunk)
    return h.hexdigest()


def header(path):
    with path.open() as f:
        assert f.readline().strip()=='FEREG_REPLAY_V1'
        rows,columns,argc,_,macros=map(int,f.readline().split());assert macros==0
        values=[]
        for _ in range(argc):
            length=int(f.readline());value=f.readline().rstrip('\n');assert len(value.encode())==length;values.append(value)
    return rows,columns,values[0],dict(v.split('=',1) for v in values[1:])


def fingerprint(data,column_hash,poisson):
    value=replay.exact_view(data,poisson);value['columns_sha256']=column_hash
    return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(',',':')).encode()).hexdigest()


def close(a,b,rule):
    return math.isfinite(a) and math.isfinite(b) and abs(a-b)<=rule['atol']+rule['rtol']*max(abs(a),abs(b))


def run(harness,plugin,case,path):
    environment=dict(os.environ,FEREG_SOLVER_TRACE='1')
    environment.pop('FEREG_SOLVER_TRACE_FILE',None)
    done=subprocess.run([str(harness),str(plugin),'--replay',str(case),str(path)],capture_output=True,text=True,timeout=120,env=environment)
    path.with_suffix('.trace').write_text(done.stderr)
    assert done.returncode==0,done.stderr[-2000:]
    data=json.loads(path.read_text())
    assert data['return_code']==0 and replay.matrix(data,'RREC')[-1]==1 and replay.matrix(data,'RCERT')[-1]==1
    return data,done.stderr


def numeric_columns(baseline,candidate,rows,columns,args,allow):
    outputs={key[7:]:int(value)-1 for key,value in args.items()
             if key.startswith('output_') and key[7:] in {'sample','drop_reason','residual','mean','eta','xb','absorbed'} and value!='0'}
    sample=outputs['sample'];drop=outputs['drop_reason']
    stats={};sample_digest=None;drop_digest=None
    with baseline.open('rb') as b,candidate.open('rb') as c:
        assert baseline.stat().st_size==candidate.stat().st_size==8*rows*columns
        b.seek(sample*rows*8);sample_values=array.array('d');sample_values.fromfile(b,rows)
        for j in range(columns):
            b.seek(j*rows*8);c.seek(j*rows*8)
            left=b.read(rows*8);right=c.read(rows*8)
            if j==sample:sample_digest=hashlib.sha256(left).hexdigest()
            if j==drop:drop_digest=hashlib.sha256(left).hexdigest()
            numerical=j in set(outputs.values())-{sample,drop} and allow
            if not numerical:assert left==right,f'exact binary column {j} changed';continue
            av=array.array('d');av.frombytes(left);bv=array.array('d');bv.frombytes(right)
            maximum=0.
            for i,(a,z) in enumerate(zip(av,bv)):
                if sample_values[i]!=1. or not math.isfinite(a) or a>=8.98846567431158e307:
                    assert left[8*i:8*i+8]==right[8*i:8*i+8],f'output layout {j}/{i}'
                else:
                    assert close(a,z,RULES['column']),f'numerical output {j}/{i}: {a} vs {z}'
                    maximum=max(maximum,abs(a-z))
            stats[str(j)]=maximum
    return outputs,[sample_digest,drop_digest],stats


def compare(base,candidate,args,column_hashes,layout_hashes,allow):
    poisson=args.get('confirm')=='feppml-estimation'
    bv=replay.exact_view(base,poisson);cv=replay.exact_view(candidate,poisson)
    if not allow:
        assert bv==cv,'unaffected scientific matrices changed'
        assert column_hashes[0]==column_hashes[1],'unaffected binary columns changed'
        return []
    prefixes=[]
    for name in ['RB','RV']:
        prefixes += [f'/matrices/{name}/bits/{i}' for i in range(len(base['matrices'][name]['bits']))]
    for mapping in (replay.numerical_scope_indices(True),replay.work_scope_indices(True)):
        for name,indices in mapping.items():
            prefix='/runtime_signature' if name=='runtime_signature' else f'/matrices/{name}/bits'
            prefixes += [f'{prefix}/{i}' for i in indices]
    changes=replay.differences(cv,bv)
    unexpected=[p for p in changes if not replay.allowed_difference(p,prefixes)]
    assert not unexpected,unexpected
    for leaf in changes:
        left,right=bv,cv
        for key in leaf.split('/')[1:]:
            left=left[int(key)] if isinstance(left,list) else left[key]
            right=right[int(key)] if isinstance(right,list) else right[key]
        for bits in (left,right):
            value=replay.number(bits)
            assert math.isfinite(value) and value<8.98846567431158e307,f'numerical presence changed: {leaf}'
    expected={'poisson':True,'outputs':{'sample':0,'drop_reason':1}}
    # Timing JSON omits columns; compare their exact sample/drop digests here.
    bas=copy.deepcopy(base);can=copy.deepcopy(candidate)
    bas['columns']=layout_hashes;can['columns']=layout_hashes
    assert replay.discrete_view(bas,expected)==replay.discrete_view(can,expected),'protected decisions changed'
    for name,rule in [('RB','coefficient'),('RV','covariance'),('RFIT','fit')]:
        av=replay.matrix(base,name);bv_=replay.matrix(candidate,name)
        for i,(a,b) in enumerate(zip(av,bv_)):
            if a!=b:assert close(a,b,RULES[rule]),f'{name}/{i} exceeds SPEC bound'
    return changes


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--phase',choices=['baseline','candidate'],required=True)
    p.add_argument('--baseline',type=Path,required=True);p.add_argument('--candidate',type=Path,required=True)
    p.add_argument('--harness',type=Path,required=True);p.add_argument('--cases',type=Path,required=True)
    p.add_argument('--output',type=Path,required=True);a=p.parse_args()
    paths={k:getattr(a,k).resolve() for k in ['baseline','candidate','harness']}
    frozen=json.loads((ROOT/'bench/standard_cases.json').read_text())
    cases={**frozen['standard']['cases'],**frozen['wide']['cases']}
    assert sorted(p.name for p in a.cases.glob('*.case'))==sorted(cases)
    for name,wanted in cases.items():assert digest(a.cases/name)==wanted,name
    identity={k:digest(v) for k,v in paths.items()}
    manifest=a.output/'preflight.json'
    if a.phase=='baseline':
        a.output.mkdir(parents=True,exist_ok=False)
        state={'rules':RULES,'identity':identity,'cases':cases,'baseline':{},'candidate':{},'passed':False}
    else:
        state=json.loads(manifest.read_text());assert state['identity']==identity and state['cases']==cases and state['rules']==RULES
        assert set(state['baseline'])==set(cases)
    def save():manifest.write_text(json.dumps(state,indent=2)+'\n')
    save()
    try:
        for name in sorted(cases):
            case=a.cases/name;rows,columns,action,request=header(case);poisson=action=='estimate-ppml'
            output=a.output/f'{case.stem}-{a.phase}.json'
            data,trace=run(paths['harness'],paths[a.phase],case,output)
            blob=output.with_suffix('.json.columns');column_hash=digest(blob)
            entry={'fingerprint':fingerprint(data,column_hash,poisson),'columns_sha256':column_hash}
            if a.phase=='candidate':
                basepath=a.output/f'{case.stem}-baseline.json';base=json.loads(basepath.read_text())
                attempted='phase=historical_preconditioner_geometry|reuse=true' in trace
                saved=request.get('output_saved_channels','.')
                unsaved=saved=='.' or all(item.split(':',1)[1]=='0' for item in saved.split('|'))
                allowed=poisson and unsaved and request['solver']=='auto' and request['memory']=='fast' and request['absorb_term_count']=='2' and attempted
                outputs,layout,stats=numeric_columns(basepath.with_suffix('.json.columns'),blob,rows,columns,request,allowed)
                entry['differences']=compare(base,data,request,[state['baseline'][name]['columns_sha256'],column_hash],layout,allowed)
                entry['attempted_reuse']=attempted;entry['column_max_absolute']=stats
                state['candidate'][name]=entry;save()
                blob.unlink();basepath.with_suffix('.json.columns').unlink()
            else:state['baseline'][name]=entry;save()
        for k,v in paths.items():assert digest(v)==identity[k]
        if a.phase=='candidate':state['passed']=True
        save()
    except BaseException as error:
        state['error']=str(error);save();raise

if __name__=='__main__':main()

