import json,os,subprocess,sys,threading,time
from pathlib import Path
T=Path(__file__).resolve().parent; R=T.parents[2]
samples=[];done=threading.Event()
def observe():
 while not done.is_set():
  ps=subprocess.check_output(['/bin/ps','-axo','pid,ppid,pcpu,comm'],text=True)
  rows=[]
  for line in ps.splitlines()[1:]:
   p=line.split(None,3)
   if len(p)==4:rows.append({'pid':int(p[0]),'parent':int(p[1]),'cpu_percent':float(p[2]),'process':Path(p[3]).name})
  owned={os.getpid()}
  for _ in range(4):owned|={r['pid'] for r in rows if r['parent'] in owned}
  external=sorted([r for r in rows if r['pid'] not in owned],key=lambda r:-r['cpu_percent'])[:12]
  samples.append({'utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'external_top':external})
  (T/'quiet-host.json').write_text(json.dumps({'period_s':30,'samples':samples},indent=2)+'\n')
  done.wait(30)
thread=threading.Thread(target=observe);thread.start()
env=dict(os.environ)
for key in ['FEREG_SOLVER_TRACE','FEREG_SOLVER_TRACE_FILE']:env.pop(key,None)
command=[sys.executable,str(R/'bench/time_exact.py'),'--plugin',f'baseline={T}/baseline.plugin','--plugin',f'candidate={T}/candidate.plugin','--cases',*[str(p) for p in sorted((T/'standard-cases').glob('*.case'))],'--output',str(T/'timing'),'--repetitions','7','--budget','2400','--timeout','90','--harness',str(T/'timing-harness'),'--result-changing']
try:
 completed=subprocess.run(command,cwd=R,env=env)
finally:
 done.set();thread.join()
sys.exit(completed.returncode)

