//! Input-only paired-score witness; never invokes the production estimator.
#[allow(dead_code)]
#[path = "../../../../../crates/fereg-oracle/tests/support/mod.rs"]
mod support;
#[allow(dead_code)]
#[path = "../../../../../crates/fereg-oracle/examples/replay/wire.rs"]
mod wire;
#[path = "../../../../../crates/fereg-oracle/examples/replay/expected.rs"]
mod expected;
use fereg_oracle::{designs::{Design,WeightKind},explicit_ols::DummyEffect};
use std::{fs,path::PathBuf};
fn main(){
    let directory=PathBuf::from(std::env::args().nth(1).expect("output directory"));
    fs::create_dir_all(&directory).unwrap();
    let n=8192;
    let g:Vec<_>=(0..n).map(|i|(i/2%8)as u32).collect();
    let h:Vec<_>=(0..n).map(|i|(i/16%8)as u32).collect();
    let xs:Vec<Vec<_>>=(0..8).map(|j|(0..n).map(|i|((i/2*(2*j+17)%997)as f64/19.).sin()).collect()).collect();
    let beta:Vec<_>=(0..8).map(|j|0.07/(j+1)as f64).collect();
    let truth:Vec<_>=(0..n).map(|i|(0.2+g[i]as f64*0.08-h[i]as f64*0.03+(0..8).map(|j|beta[j]*xs[j][i]).sum::<f64>()).exp()).collect();
    let outcome=truth.iter().enumerate().map(|(i,m)|m*if i%2==0{0.8}else{1.2}).collect();
    let design=Design{outcome,regressors:xs,effects:vec![DummyEffect::new(g,8,true,Vec::new()).unwrap(),DummyEffect::new(h,8,true,Vec::new()).unwrap()],weights:vec![1.;n],weight_kind:WeightKind::Unit,missing:vec![false;n],clusters:vec![]};
    let mut request=wire::make(&design,true,"robust","auto",false);
    request.replace("poolsize","8");request.replace("keep_singletons","1");
    let name="ppml-historical-preconditioner-known-optimum";
    request.write(&directory.join(format!("{name}.case")));
    expected::write(&directory.join(format!("{name}.json")),&design,true,"robust",&request);
    fs::write(directory.join(format!("{name}.truth.json")),format!("{{\"beta\":{beta:?},\"mean\":{truth:?},\"bound\":1e-10,\"proof\":\"Each adjacent identical-design pair has opposite 20% deviations; every finite and dummy score vanishes at the specified mean.\"}}\n")).unwrap();
}
